const body = $json.body || {};
if (!body.systemPrompt || !body.userPrompt) throw new Error('Missing matching prompt');
if (!Number.isFinite(Number(body.targetId)) || !Number.isFinite(Number(body.fallbackScore))) throw new Error('Invalid matching request');
return items;

const request = $('Worker Match Webhook').first().json.body;
const response = $input.first().json;
const content = response.choices?.[0]?.message?.content;
if (typeof content !== 'string' || !content.trim()) throw new Error('DeepSeek returned no JSON content');
const cleaned = content.trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
const parsed = JSON.parse(cleaned);
const parsedScore = Number(parsed.aiScore);
const candidate = Number.isFinite(parsedScore) ? (parsedScore >= 0 && parsedScore <= 1 ? parsedScore * 100 : parsedScore) : Number(request.fallbackScore);
const score = Math.round(Math.max(0, Math.min(100, candidate)));
const strings = value => Array.isArray(value) ? value.map(item => String(item).trim()).filter(Boolean).slice(0, 5) : [];
return [{ json: {
  targetId: Number(request.targetId),
  aiScore: score,
  fallbackScore: Number(request.fallbackScore),
  label: String(parsed.label || (score >= 80 ? 'Strong match' : score >= 60 ? 'Good match' : 'Possible match')),
  explanation: String(parsed.explanation || 'DeepSeek evaluated the supplied non-identifying worker and shift details.'),
  strengths: strings(parsed.strengths),
  risks: strings(parsed.risks),
  recommendedAction: String(parsed.recommendedAction || 'Review the shift details before applying.'),
  source: 'N8N_DEEPSEEK'
} }];
